/* Generated by port_pages.py from the approved mockup. Behaviour for the pricing page; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce;

  /* monthly / yearly: prices roll to the other figure */
  var bb = [].slice.call(document.querySelectorAll(".bill button"));
  bb.forEach(function (b) {
    ctx.on(b, "click", function () {
      var y = b.dataset.b === "y";
      bb.forEach(function (x) {
        x.classList.toggle("on", x === b);
      });
      [].forEach.call(document.querySelectorAll(".plan .prc b"), function (el) {
        var to = y ? el.dataset.y : el.dataset.m;
        if (reduce || !el.animate) {
          el.textContent = to;
          return;
        }
        el.animate(
          [
            { opacity: 1, transform: "none" },
            { opacity: 0, transform: "translateY(-8px)" },
          ],
          { duration: 160, easing: "ease-in" },
        ).onfinish = function () {
          el.textContent = to;
          el.animate(
            [
              { opacity: 0, transform: "translateY(8px)" },
              { opacity: 1, transform: "none" },
            ],
            { duration: 260, easing: "cubic-bezier(.22,1,.36,1)" },
          );
        };
      });
      [].forEach.call(document.querySelectorAll(".plan .yr"), function (el) {
        el.textContent = y ? el.dataset.y : "";
      });
    });
  });
  /* phones: one plan at a time; the compare table follows the same plan */
  var pp = [].slice.call(document.querySelectorAll(".pp button"));
  pp.forEach(function (b) {
    ctx.on(b, "click", function () {
      var k = b.dataset.p;
      pp.forEach(function (x) {
        x.classList.toggle("on", x === b);
      });
      [].forEach.call(document.querySelectorAll("[data-p]"), function (el) {
        if (el.tagName !== "BUTTON")
          el.classList.toggle("show", el.dataset.p === k);
      });
    });
  });
}
